const toArr = (name) => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };
const num = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
const daysAgo = (n) => Date.now() - n * 24 * 3600 * 1000;
const tsOf = (v) => { if (v == null || v === '') return NaN; const n = Number(v); if (Number.isFinite(n) && String(v).length >= 10) return n < 1e12 ? n * 1000 : n; return new Date(v).getTime(); };
const dealsRaw = toArr('HubSpot Deals');
const contactsRaw = toArr('HubSpot Contacts');
const calls = toArr('Get Calls');
const emailsSent = toArr('Get Sent Emails');
const inbox = toArr('Get Inbox');
const expensesRaw = toArr('Get Expenses');
const churnRaw = toArr('Get Churn');
const tasksRaw = toArr('Get Tasks');
const dealProp = (d, key) => { const p = d.properties || {}; const v = p[key]; if (v == null) return undefined; return typeof v === 'object' ? v.value : v; };
const STAGE_WON = '5698192620';
const STAGE_LABELS = { '5698192615': 'In Progress', '5698192620': 'Closed Won' };
const STAGE_PROB = { '5698192615': 55, '5698192620': 100 };
const deals = dealsRaw.map(d => ({ dealname: dealProp(d, 'dealname') || '(unnamed deal)', email: dealProp(d, 'email') || '', product: dealProp(d, 'product') || '', tier: dealProp(d, 'tier') || '', dealstage: dealProp(d, 'dealstage') || '', amount: num(dealProp(d, 'amount')), createdate: dealProp(d, 'createdate') || '' }));
const dealsByCreatedDesc = deals.slice().sort((a, b) => tsOf(b.createdate) - tsOf(a.createdate));
const newLeads7d = deals.filter(d => tsOf(d.createdate) >= daysAgo(7)).length;
const newLeads30d = deals.filter(d => tsOf(d.createdate) >= daysAgo(30)).length;
const byStage = {};
for (const d of deals) { const s = d.dealstage || 'unknown'; byStage[s] = (byStage[s] || 0) + 1; }
const openDeals = deals.filter(d => d.dealstage && d.dealstage !== STAGE_WON);
const pipelineValue = openDeals.reduce((s, d) => s + d.amount, 0);
const forecastStageMap = {};
for (const d of deals) { if (!d.dealstage) continue; const key = d.dealstage; if (!forecastStageMap[key]) forecastStageMap[key] = { stage: STAGE_LABELS[key] || key, count: 0, valueZAR: 0, probability: STAGE_PROB[key] != null ? STAGE_PROB[key] : 50 }; forecastStageMap[key].count += 1; forecastStageMap[key].valueZAR += d.amount; }
const forecastByStage = Object.values(forecastStageMap).map(s => ({ stage: s.stage, count: s.count, valueZAR: s.valueZAR, probability: s.probability, weightedZAR: Math.round(s.valueZAR * s.probability / 100) }));
const weightedForecast = forecastByStage.reduce((s, r) => s + r.weightedZAR, 0);
const contactProp = (c, key) => { const p = c.properties || {}; const v = p[key]; if (v == null) return undefined; return typeof v === 'object' ? v.value : v; };
const contacts = contactsRaw.map(c => ({ source: contactProp(c, 'hs_analytics_source') || contactProp(c, 'lead_source') || 'Unknown', createdate: contactProp(c, 'createdate') || '' }));
const sourceMap = {};
for (const c of contacts) { sourceMap[c.source] = (sourceMap[c.source] || 0) + 1; }
const sources = Object.entries(sourceMap).map(([source, count]) => ({ source, count })).sort((a, b) => b.count - a.count);
const totalCalls = calls.length;
const totalMinutes = Math.round(calls.reduce((s, c) => s + num(c.duration_min), 0));
const connected = calls.filter(c => c.connected === true || c.connected === 'true').length;
const booked = calls.filter(c => c.booked === true || c.booked === 'true').length;
const bookingRate = totalCalls ? Math.round((booked / totalCalls) * 1000) / 10 : 0;
const recentCalls = calls.slice().sort((a, b) => tsOf(b.ts) - tsOf(a.ts)).slice(0, 50).map(c => ({ ts: c.ts, client_key: c.client_key, call_type: c.call_type, duration_min: num(c.duration_min), connected: c.connected === true || c.connected === 'true', booked: c.booked === true || c.booked === 'true' }));
const now = new Date();
const thisMonthKey = now.getFullYear() + '-' + (now.getMonth() + 1);
const lastMonthDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const lastMonthKey = lastMonthDate.getFullYear() + '-' + (lastMonthDate.getMonth() + 1);
const monthKeyOf = (d) => { const dt = new Date(d); return dt.getFullYear() + '-' + (dt.getMonth() + 1); };
const expenses = expensesRaw.map(e => ({ date: e.date, category: e.category || 'Other', description: e.description || '', amountZAR: num(e.amount_cents) / 100 }));
const thisMonthZAR = expenses.filter(e => monthKeyOf(e.date) === thisMonthKey).reduce((s, e) => s + e.amountZAR, 0);
const lastMonthZAR = expenses.filter(e => monthKeyOf(e.date) === lastMonthKey).reduce((s, e) => s + e.amountZAR, 0);
const expenseCatMap = {};
for (const e of expenses.filter(x => monthKeyOf(x.date) === thisMonthKey)) { expenseCatMap[e.category] = (expenseCatMap[e.category] || 0) + e.amountZAR; }
const expenseCategories = Object.entries(expenseCatMap).map(([category, amountZAR]) => ({ category, amountZAR }));
const recentExpenses = expenses.slice().sort((a, b) => tsOf(b.date) - tsOf(a.date)).slice(0, 50);
const churn = churnRaw.map(c => ({ dealname: c.dealname, product: c.product || '', tier: c.tier || '', cancelledAt: c.cancelled_at, reason: c.reason || '', mrrZAR: num(c.mrr_cents) / 100 }));
const churn30 = churn.filter(c => tsOf(c.cancelledAt) >= daysAgo(30));
const mrrLostZAR = churn30.reduce((s, c) => s + c.mrrZAR, 0);
const wonCount = deals.filter(d => d.dealstage === STAGE_WON).length;
const churnRateMonthly = wonCount ? Math.round((churn30.length / wonCount) * 1000) / 10 : 0;
const recentChurn = churn.slice().sort((a, b) => tsOf(b.cancelledAt) - tsOf(a.cancelledAt)).slice(0, 50);
const tasks = tasksRaw.map(t => ({ title: t.title, relatedTo: t.related_to || '', dueDate: t.due_date, priority: t.priority || 'Low', status: t.status || 'open' }));
const openTasks = tasks.filter(t => t.status !== 'done');
const overdueTasks = openTasks.filter(t => t.status === 'overdue' || (t.dueDate && tsOf(t.dueDate) < Date.now()));
const recentTasks = tasks.slice().sort((a, b) => tsOf(a.dueDate) - tsOf(b.dueDate)).slice(0, 50);
const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
const recvRecent = inbox.slice().sort((a, b) => tsOf(b.received_at) - tsOf(a.received_at)).slice(0, 50);
const sentByTypeMap = {};
for (const e of emailsSent) { const k = e.email_type || 'other'; sentByTypeMap[k] = (sentByTypeMap[k] || 0) + 1; }
const sentByType = Object.entries(sentByTypeMap).map(([type, count]) => ({ type, count }));
const sentRecent = emailsSent.slice().sort((a, b) => tsOf(b.sent_at) - tsOf(a.sent_at)).slice(0, 50);
const data = { payments: { totalRevenueZAR: 0, revenue30dZAR: 0, successCount: 0, failedCount: 0, revenueTrend: [], recentTransactions: [] }, pipeline: { totalDeals: deals.length, newLeads7d, newLeads30d, byStage, recentDeals: dealsByCreatedDesc.slice(0, 50).map(d => ({ dealname: d.dealname, email: d.email, product: d.product, tier: d.tier, dealstage: d.dealstage, createdate: d.createdate })) }, calls: { totalCalls, totalMinutes, connected, booked, bookingRate, recentCalls }, accounts: { mrrZAR: 0, atRisk: [], usage: [] }, leadSources: { totalContacts: contacts.length, new7d: contacts.filter(c => tsOf(c.createdate) >= daysAgo(7)).length, new30d: contacts.filter(c => tsOf(c.createdate) >= daysAgo(30)).length, sources }, expenses: { thisMonthZAR, lastMonthZAR, categories: expenseCategories, recent: recentExpenses }, churn: { churned30d: churn30.length, churnRateMonthly, mrrLostZAR, recent: recentChurn }, tasks: { openCount: openTasks.length, overdueCount: overdueTasks.length, recent: recentTasks }, forecast: { pipelineValueZAR: pipelineValue, weightedForecastZAR: weightedForecast, byStage: forecastByStage, monthlyForecastTrend: [] }, emails: { received: { total: inbox.length, newToday: inbox.filter(e => tsOf(e.received_at) >= startOfToday).length, recent: recvRecent }, sent: { total: emailsSent.length, byType: sentByType, recent: sentRecent } } };
return [{ json: data }];

const b = $json.body || $json;
const cents = Number(b.amount_cents);
return [{ json: { date: b.date || new Date().toISOString().slice(0, 10), category: (b.category || 'Other').toString(), description: (b.description || '').toString(), amount_cents: Number.isFinite(cents) ? Math.round(cents) : 0 } }];
